-- Scope recipient-confirmation checks to source families where a recipient/partner confirmation exists.
update community_impact_score_policy_version set status='superseded' where version=4 and status='active';
insert into community_impact_score_policy_event(policy_version_id,event_code,rationale,metadata)
select id,'superseded','Replaced by initial policy v5 with explicit recipient-confirmation source-family scope.',jsonb_build_object('replacedByVersion',5)
from community_impact_score_policy_version where version=4
and not exists(select 1 from community_impact_score_policy_event e where e.policy_version_id=community_impact_score_policy_version.id and e.event_code='superseded');
insert into community_impact_score_policy_version(version,schema_version,policy_hash,policy,status,evaluation_only,public_score_enabled,rationale,change_summary,created_by)
values(5,1,'9159082c92547823a1c7cd11690ba1683de60c405c154009022e5f9caff20cf7','{"mode":"evaluation","publicScoreEnabled":false,"dimensions":[{"key":"measurable_community_outcomes","label":"Measurable community outcomes","weight":30,"minimumEvidenceQuality":"adequate","ratings":{"min":0,"max":5,"step":1},"criteria":["Documented result or change","Reach and beneficiary evidence","Evidence connecting contribution to outcome"],"measurementRules":{"requiresVerifiedOutcome":true,"followUpDays":0,"minimumOutcomeMaturity":"outcome"}},{"key":"quality_and_significance","label":"Quality and significance","weight":25,"minimumEvidenceQuality":"adequate","ratings":{"min":0,"max":5,"step":1},"criteria":["Reliability and strength of evidence","Significance and scope of contribution","Quality of delivery"],"measurementRules":{"requiresEvidenceReferences":true}},{"key":"verified_contribution_responsibility","label":"Verified contribution and responsibility","weight":20,"minimumEvidenceQuality":"adequate","ratings":{"min":0,"max":5,"step":1},"criteria":["Verified contributor identity and role","Attributable contribution share","Responsibility actually performed"],"measurementRules":{"requiresVerifiedAttribution":true}},{"key":"sustainability","label":"Sustainability","weight":15,"minimumEvidenceQuality":"adequate","ratings":{"min":0,"max":5,"step":1},"criteria":["Durability or continuation evidence","Maintenance or ownership plan","Follow-up evidence where available"],"measurementRules":{"followUpDays":0,"requiresFollowUpEvidence":false}},{"key":"collaboration_knowledge_sharing","label":"Collaboration and knowledge sharing","weight":10,"minimumEvidenceQuality":"adequate","ratings":{"min":0,"max":5,"step":1},"criteria":["Recipient or partner confirmation","Knowledge shared or transferred","Collaboration quality and reciprocal contribution"],"measurementRules":{"requiresRecipientConfirmation":true,"recipientConfirmationSourceTypes":["serve_community_participation","offline_completed_project","mentorship","professional_service","employment_referral","network_plus_collaboration","network_plus_partnership"]}}],"calculation":{"basePoints":100,"rounding":"4dp","roleFactors":{"lead":1,"co_lead":1,"contributor":1,"mentor":1,"reviewer_organizer":1,"partner_organization":1,"other":1},"minimumEvidenceQuality":"adequate","evidenceQualityRank":{"insufficient":0,"limited":1,"adequate":2,"strong":3,"exceptional":4},"minimumOutcomeMaturity":"output","outcomeMaturityRank":{"activity":0,"output":1,"outcome":2,"sustained_impact":3},"requiredAssessmentStatus":"approved","requiredClaimStatus":"verified","sourceCaps":{},"categoryCaps":{},"periodCaps":{},"diminishingReturns":[],"modifiers":[],"decayRules":[],"eligibleSourceTypes":["serve_community_participation","offline_completed_project","mentorship","professional_service","employment_referral","network_plus_collaboration","network_plus_partnership","historical_contribution"]},"publication":{"enabled":false,"consentRequired":true,"minimumGroupSize":5}}'::jsonb,'active',true,false,
'Initial docs/62 scoring baseline with source-specific recipient confirmation rules; approved five weights unchanged; private evaluation only.',
'Operational scoring policy v5; recipient confirmation is required only for source families that support it.',null)
on conflict(version) do nothing;
update community_impact_score_active_policy set policy_version_id=(select id from community_impact_score_policy_version where version=5),activated_by=null,activated_at=now() where singleton=true;
insert into community_impact_score_policy_event(policy_version_id,event_code,rationale,metadata)
select id,'activated','Activated initial docs/62 scoring baseline v5 for private evaluation only.',jsonb_build_object('version',5,'publicScoreEnabled',false)
from community_impact_score_policy_version where version=5
and not exists(select 1 from community_impact_score_policy_event e where e.policy_version_id=community_impact_score_policy_version.id and e.event_code='activated');
